module.exports = /*#__PURE__*/JSON.parse('{"title":"束硬化和双能CT","description":"本页面介绍CT中的束硬化效应和双能CT技术，包括X射线能量和衰减、束硬化、双能X射线摄影和双能重建。","sections":[{"id":"xray-energy","title":"X射线能量和衰减","description":"X射线在不同能量下通过不同材料的衰减特性是双能CT的基础。","content":"为了理解双能CT，我们首先需要理解X射线在不同能量下通过不同材料的衰减特性。在诊断能量范围内，X射线与物质相互作用的两个重要物理过程是光电效应和康普顿（非相干）散射。康普顿散射在大多数材料中相对相似，但光电吸收的可能性差异很大。具体来说，光电事件的可能性与(Z/E)³成正比，其中Z是原子序数，E是X射线光子能量。这意味着它强烈依赖于材料，但也重要的是依赖于X射线能量。","simulator":{"type":"xray-attenuation","options":{"tissues":[{"id":"soft_tissue","name":"软组织（如肌肉）"},{"id":"fat","name":"脂肪"},{"id":"bone","name":"骨骼"},{"id":"iodine","name":"碘造影剂"},{"id":"iodine_enhanced","name":"碘增强器官"},{"id":"water","name":"水"},{"id":"air","name":"空气"}],"iodineConcentrations":[1,2,5,8,10]}},"keyPoints":["X射线衰减主要由光电效应和康普顿散射决定","光电效应强烈依赖于材料的原子序数和X射线能量","K边缘是光电事件发生所需的最小能量","碘的K边缘在33 keV，正好在诊断X射线能量范围内","CT值（HU）与线性衰减系数直接相关，但经过标准化处理"]},{"id":"beam-hardening","title":"束硬化","description":"束硬化是X射线束通过物质时低能量X射线被优先吸收，导致平均能量增加的现象。","content":"当X射线束通过物质时，低能量的X射线比高能量的X射线更容易被吸收。这导致穿过物质的X射线束的平均能量增加，我们称这种现象为束硬化。束硬化可能导致CT图像中出现伪影，特别是在高密度物体（如金属植入物或骨骼）周围。","simulator":{"type":"beam-hardening","options":{"materials":[{"id":"aluminum","name":"铝（2.5mm）"},{"id":"titanium","name":"钛（5mm）"},{"id":"bone","name":"骨骼（1cm）"}],"kVs":[80,100,120,140]}},"keyPoints":["束硬化是X射线束通过物质时低能量X射线被优先吸收的现象","束硬化可能导致CT图像中出现伪影","滤波器可以通过预先去除低能量X射线来减少束硬化","束硬化校正算法可以在图像重建过程中减少伪影"]},{"id":"dual-energy-radiography","title":"双能X射线摄影","description":"双能X射线摄影利用不同能量X射线的衰减差异来区分不同材料。","content":"双能X射线摄影是双能CT的前身，它利用不同能量X射线的衰减差异来区分不同材料。例如，骨骼和软组织在低能量和高能量X射线下的衰减差异很大，这可以用来创建只显示软组织或只显示骨骼的图像。双能X射线摄影在骨密度测量（DXA扫描）中广泛应用。","keyPoints":["双能X射线摄影利用不同能量X射线的衰减差异来区分不同材料","它可以用来创建只显示软组织或只显示骨骼的图像","双能X射线摄影在骨密度测量中广泛应用"]},{"id":"dual-energy-ct","title":"双能CT系统","description":"双能CT系统使用两种不同能量的X射线来获取更多关于组织成分的信息。","content":"双能CT系统使用两种不同能量的X射线来获取更多关于组织成分的信息。有几种实现双能CT的方法：双源CT（两个X射线管和探测器组），快速kV切换（单个X射线管在高低kV之间快速切换），双层探测器（上层探测低能量X射线，下层探测高能量X射线）和分离束（使用滤波器将X射线束分成高能和低能部分）。","keyPoints":["双能CT使用两种不同能量的X射线来获取更多关于组织成分的信息","实现双能CT的方法包括双源CT、快速kV切换、双层探测器和分离束","双能CT可以提供常规CT无法获得的材料特性信息"]},{"id":"dual-energy-reconstruction","title":"双能重建","description":"双能CT可以进行材料分解，创建虚拟平扫、碘叠加、骨骼减除和肺灌注等特殊图像。","content":"双能CT的主要优势在于它可以进行材料分解，区分不同的材料成分。这使得可以创建多种特殊图像，包括：虚拟平扫（移除碘造影剂的影响，模拟未注射造影剂的图像），碘叠加（突出显示含碘区域），骨骼减除（移除骨骼，便于观察血管和软组织）和肺灌注（评估肺部血流）。","simulator":{"type":"dual-energy-reconstruction","options":{"reconstructionTypes":[{"id":"virtual_noncontrast","name":"虚拟平扫"},{"id":"iodine_overlay","name":"碘叠加"},{"id":"bone_subtraction","name":"骨骼减除"},{"id":"lung_perfusion","name":"肺灌注"}],"cases":[{"id":"liver","name":"肝脏病变"},{"id":"lung","name":"肺栓塞"},{"id":"kidney","name":"肾结石"}]}},"keyPoints":["双能CT可以进行材料分解，区分不同的材料成分","虚拟平扫可以减少对比剂增强检查的需求","碘叠加可以提高病变检测率","骨骼减除简化了血管和软组织的评估","肺灌注图像可以帮助评估肺栓塞"]}]}');

